package io.scenariomesh.coordinator;import java.io.File;import java.nio.file.Path;import java.util.*;final class JavaProcessSupport{private JavaProcessSupport(){}static List<String> command(List<Path> cp,List<String>jvm,Map<String,String>props,String main,List<String>args){List<String>c=new ArrayList<>();c.add(javaExecutable().toString());c.addAll(jvm);props.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->c.add("-D"+e.getKey()+"="+e.getValue()));c.add("-cp");c.add(cp.stream().map(Path::toString).reduce((a,b)->a+File.pathSeparator+b).orElse(""));c.add(main);c.addAll(args);return c;}private static Path javaExecutable(){boolean windows=System.getProperty("os.name","").toLowerCase().contains("win");return Path.of(System.getProperty("java.home"),"bin",windows?"java.exe":"java");}}
